<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasOne;

/**
 * A line of a PI. total_qty, amount, total_cbm and total_kg are generated by PostgreSQL (I5);
 * never write them. Lines change only while their PI is a draft (trigger). Written only by
 * App\Services\ProformaInvoices\ProformaInvoiceService.
 */
class PiLine extends Model
{
    use HasFactory;

    protected $guarded = ['id', 'total_qty', 'amount', 'total_cbm', 'total_kg'];

    protected function casts(): array
    {
        return [
            'cartons' => 'decimal:4', 'qty_per_carton' => 'decimal:4', 'total_qty' => 'decimal:4',
            'unit_price' => 'decimal:4', 'amount' => 'decimal:4', 'cbm_per_carton' => 'decimal:4',
            'kg_per_carton' => 'decimal:4', 'total_cbm' => 'decimal:4', 'total_kg' => 'decimal:4',
            'supplier_price' => 'decimal:4',
        ];
    }

    public function proformaInvoice(): BelongsTo
    {
        return $this->belongsTo(ProformaInvoice::class);
    }

    public function product(): BelongsTo
    {
        return $this->belongsTo(Product::class);
    }

    public function supplier(): BelongsTo
    {
        return $this->belongsTo(Party::class, 'supplier_id');
    }

    public function supplierOrderLine(): HasOne
    {
        return $this->hasOne(SupplierOrderLine::class);
    }

    /** "ITEM NAME & DESCRIPTION" as printed: the line's own text, else its product's name. */
    public function itemText(): string
    {
        return filled($this->description) ? (string) $this->description : (string) $this->product?->name;
    }
}
